SHORT = {'Conselho de Turismo de Ivalice': 'Turismo de Ivalice', 'Escritório de Eventos de Bervenia': 'Eventos de Bervenia',
         'Guilda dos Farmacêuticos de Ivalice': 'Farmacêuticos de Ivalice', 'Administração do Banco de Monstros': 'Banco de Monstros',
         'Associação da Praça do Mercado': 'Praça do Mercado', 'Comitê do Torneio de Batalha': 'Torneio de Batalha',
         'Comitê do Torneio de Magos': 'Torneio de Magos', 'Palácio de Bervenia e Juízes': 'Palácio e Juízes'}


def fit(rom, code01, px, limit=147, Q=Q):
    """Encurta assinaturas (depois de {40 3e 10}) que passam do limite: troca por forma curta ou só o nome."""
    out, rep = {}, []
    for k, t in Q.items():
        if S in t:
            head, sig = t.rsplit(S, 1)
            for a, b in SHORT.items(): sig = sig.replace(a, b)
            if px(rom, code01, sig) > limit and ',' in sig:
                sig = sig.split(',')[0]
            while px(rom, code01, sig) > limit and ' ' in sig: sig = sig.rsplit(' ', 1)[0]
            t = head + S + sig
        out[k] = t
    return out
